821	      y = scrollY || pageYOffset;
822	      var driftA = null, driftB = null, driftT = 0;
823	      var maxY = Math.max((document.documentElement.scrollHeight || 0) - vh, 1);
824	
825	      for (var i = 0; i < acts.length; i++) {
826	        var a = acts[i];
827	        var raw;
828	        if (a.pinned) {
829	          var travel = Math.max(a.height - vh, 1);
830	          raw = clamp01((y - a.top) / travel);
831	        } else {
832	          raw = clamp01((y + vh - a.top) / (a.height + vh));
833	        }
834	        a.raw = raw;
835	        a.p = a.dwell ? dwell(raw, a.dwell) : raw;
836	
837	        // Clip time is NOT cue time. Cues belong to the pin, so they keep using
838	        // `p`. The clip belongs to the stage, and the stage is on screen for one
839	        // viewport before the pin starts and one after it ends. Driving the clip
840	        // from `p` therefore parks it on frame one for the whole entry slide and
841	        // on its last frame for the whole exit slide, which is a still
842	        // photograph moving up the screen under the reader's hand.
843	        //
844	        // So map the clip across the stage's entire visible life instead. Both
845	        // ends are clamped to scroll that actually exists: an act at the top of
846	        // the document has no entry slide and must still start on frame one, and
