/* Underneath: the template page. Clipped to everything LEFT of the seam, so the
   filtered area shrinks with --split instead of always covering the frame. */
.layer--before {
  clip-path: inset(0 calc(100% - var(--split) * 100%) 0 0);
  /* The only filter on the page. It sits on the WRAPPER, never on the frame
     itself: a shown frame is never transformed or faded (PRODUCT.md). */
  filter: saturate(calc(1 - 0.75 * var(--d)));
}

/* On top: Calyx. Clipped to everything RIGHT of the seam, so it grows leftward
   as --split falls. The frame is never scaled, moved or faded — only the clip
   boundary travels (F-010: the surface that fills the frame at ps = 1 is the
   same frame that stood on the right at ps = 0). */
.layer--after {
  clip-path: inset(0 0 0 calc(var(--split) * 100%));
}

